'use strict';
function catArt(coat='#bca48c',accent='#8c7561'){return `<svg viewBox="0 0 110 100" aria-hidden="true"><ellipse cx="54" cy="94" rx="37" ry="4" fill="#2e2a27" opacity=".07"/><path class="tail" d="M77 79 C105 83 104 48 91 54 C83 58 103 74 79 72" stroke="${accent}" stroke-width="10" fill="none" stroke-linecap="round"/><path d="M29 89 C24 63 33 47 53 47 C77 47 83 68 77 90Z" fill="${coat}"/><ellipse cx="51" cy="78" rx="17" ry="17" fill="#f1e7d9" opacity=".6"/><path d="M25 44 L24 12 Q35 13 42 24 Q53 19 64 24 Q76 12 82 14 L80 46 Q77 63 53 64 Q28 63 25 44" fill="${coat}"/><path d="M29 20 L30 34 L39 28Z M76 21 L68 29 L77 34Z" fill="#d99f89"/><g class="eye-open" fill="#453b33"><ellipse cx="41" cy="42" rx="2.5" ry="3.5"/><ellipse cx="65" cy="42" rx="2.5" ry="3.5"/></g><g class="eye-rest" stroke="#453b33" stroke-width="2" stroke-linecap="round" fill="none"><path d="M36 43 Q41 47 46 43 M60 43 Q65 47 70 43"/></g><path d="M50 48 Q53 46 56 48 L53 51Z" fill="#a36656"/><path d="M53 51 Q49 56 46 52 M53 51 Q56 56 60 52" stroke="#765e4d" stroke-width="1.2" fill="none" stroke-linecap="round"/><path d="M22 46 L35 48 M22 51 L35 51 M72 48 L85 46 M72 51 L85 51" stroke="#8c7561" stroke-width="1" opacity=".7"/><path d="M38 86 L38 92 M66 86 L66 92" stroke="${accent}" stroke-width="2" stroke-linecap="round"/><ellipse cx="36" cy="93" rx="11" ry="4" fill="${coat}"/><ellipse cx="69" cy="93" rx="11" ry="4" fill="${coat}"/><path class="pet-heart" d="M84 12 C77 5 73 15 84 21 C95 15 91 5 84 12Z"/></svg>`;}
let catsHidden=false,catMessageTimer=null,chatMessages=[],chatMode='understand',chatConsent=false,chatBusy=false,chatError='',chatDraft='',chatController=null,chatVersion=0,chatConfig=null;
const moodNames=['','Very low','Low','Somewhere between','Okay','Good'];
const catStates={1:['rest','quiet'],2:['quiet','rest'],3:['curious','quiet'],4:['quiet','curious'],5:['play','curious']};
const originalRoute=route;
route=function(){if((location.hash.slice(1)||'home')==='chat'){$('#main').innerHTML=chatPage();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#chat'));bindChat();}else{originalRoute();if((location.hash.slice(1)||'home')==='home'){const feature=$('.feature');if(feature)feature.innerHTML=`<p class="eyebrow">PULL UP A LITTLE SPACE</p><h2>You can talk<br>about it here.</h2><p class="small">No perfect words needed. A thoughtful AI conversation, one thing at a time.</p><a class="primary home-chat-cta" href="#chat">Talk with Aura &nbsp; ↗</a><div class="cat-hero">${catArt('#b3c0aa','#7a9382')}</div>`;}if(location.hash==='#settings'){const sections=document.querySelectorAll('#main section');if(sections[0])sections[0].insertAdjacentHTML('beforeend','<h3>AI chat privacy</h3><p>Chat messages and the recent conversation are sent to Google Gemini only when you opt in and press Send. Journal entries and mood check-ins are not included. Chat stays in this tab and is excluded from browser saving and data export. Google’s API data terms apply; Aura cannot delete provider-retained data.</p><p><a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Google Gemini API terms</a></p>');}}renderCats();};
function renderCats(){let shelf=$('#cat-shelf');if(!shelf){shelf=document.createElement('div');shelf.id='cat-shelf';document.body.append(shelf);}if(catsHidden){shelf.className='';shelf.innerHTML='<button class="cat-restore" data-cats="show">Bring back the cats ♡</button>';return;}const mood=selectedMood||state.moods.at(-1)?.value||3,poses=catStates[mood]||catStates[3];shelf.className='cat-shelf';shelf.innerHTML=`<div class="cat-controls"><button data-cats="pause" aria-pressed="${document.body.classList.contains('cats-paused')}">${document.body.classList.contains('cats-paused')?'Resume':'Pause'} cats</button><button data-cats="hide">Hide cats</button></div><div class="cat-group"><div id="cat-note" class="cat-note" role="status" hidden></div><button class="cat-button" data-cat="Miso" data-state="${poses[0]}" aria-label="Pet Miso the cat. ${moodNames[mood]} mood setting.">${catArt()}</button><button class="cat-button" data-cat="Mochi" data-state="${poses[1]}" aria-label="Pet Mochi the cat. ${moodNames[mood]} mood setting.">${catArt('#9eae98','#71836c')}</button></div>`;}
function chatPage(){return heading('A CONVERSATION, AT YOUR PACE','What’s on your mind?','You can start anywhere. Aura is AI support, not a therapist. You stay in charge of what you share.')+`<div class="chat-layout"><section class="card chat-window" aria-label="Conversation with Aura"><div class="chat-topline"><div class="chat-identity"><span class="chat-avatar">✧</span><div><strong>Aura</strong><small>AI reflection companion · Google Gemini</small></div></div><div class="chat-tools"><button data-chat="save">Save to journal</button><button data-chat="new">New chat</button></div></div><div class="chat-modes" aria-label="Conversation style">${[['listen','Just listen'],['understand','Help me understand'],['steps','Find a next step']].map(([id,name])=>`<button data-mode="${id}" aria-pressed="${chatMode===id}">${name}</button>`).join('')}</div><div class="chat-transcript" id="chat-transcript" role="log" aria-live="polite" aria-label="Chat messages">${chatMessages.length?chatMessages.map(m=>`<div class="message ${m.role}"><div class="bubble"><span class="message-label">${m.role==='user'?'You':'Aura · AI'}</span>${esc(m.text)}</div></div>`).join(''):`<div class="chat-empty"><p class="eyebrow">NO PERFECT PLACE TO START</p><h2>Let’s start with you.</h2><p>What feels heavy, confusing, or simply worth talking about today?</p><div class="starters">${['I can’t stop overthinking.','I’ve been feeling disconnected.','Something happened and I want to unpack it.'].map(x=>`<button class="starter" data-starter="${esc(x)}">${x}</button>`).join('')}</div></div>`}${chatBusy?'<div class="typing" aria-label="Aura is responding"><span></span><span></span><span></span></div>':''}</div>${chatError?`<div class="chat-error" role="alert">${esc(chatError)} <button class="secondary" data-chat="retry">Retry</button></div>`:''}<div class="chat-consent"><label class="check"><input type="checkbox" id="chat-consent" ${chatConsent?'checked':''}> <span>I agree to send my chat and recent conversation to Google Gemini for AI replies. My journal and mood history are not shared. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Provider terms</a>.</span></label></div><form id="chat-form" class="chat-compose"><label for="chat-input">Your message</label><textarea id="chat-input" maxlength="6000" placeholder="What would you like to talk about?" ${chatBusy?'disabled':''}>${esc(chatDraft)}</textarea><div class="actions"><p class="small">Chat stays in this tab unless you save it to your journal. No one is monitoring this conversation.</p><button class="primary" id="chat-send" ${chatBusy||!chatConsent?'disabled':''}>${chatBusy?'Listening…':'Send message ↗'}</button></div><p class="chat-status" id="chat-status">${chatMessages.length/2>=19?'This conversation is nearly full. Save it, then start a new chat.':'Enter to send · Shift + Enter for a new line'}</p></form></section><aside class="chat-rail" aria-label="Conversation resources"><div class="card"><h3>A little space to be heard.</h3><p>Choose listening, understanding, or a next step. You can change direction whenever you like.</p></div><div class="card"><h3>Need a pause?</h3><p>It’s okay to step away. Your conversation will wait in this tab.</p><a href="#ground">Try grounding →</a></div><div class="card"><h3>More support is allowed.</h3><p>If you feel unsafe or need urgent care, contact local emergency services and someone you trust. Aura cannot contact help.</p><a href="#support">Human support →</a></div></aside></div>`;}
function bindChat(){const input=$('#chat-input');input.addEventListener('input',()=>chatDraft=input.value);input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!chatBusy)sendChat();}});$('#chat-form').addEventListener('submit',e=>{e.preventDefault();sendChat();});$('#chat-consent').addEventListener('change',e=>{chatConsent=e.target.checked;$('#chat-send').disabled=!chatConsent||chatBusy;});const transcript=$('#chat-transcript');transcript.scrollTop=transcript.scrollHeight;}
async function sendChat(retry=false){if(chatBusy)return;if(!chatConsent){toast('Please choose whether to share this conversation with Google first.');return;}const text=chatDraft.trim();if(!retry&&!text)return;if(!retry&&chatMessages.length>=38){toast('Please save this conversation and start a new chat.');return;}if(!retry){if(chatMessages.at(-1)?.role==='user')chatMessages.pop();chatMessages.push({role:'user',text});chatDraft='';}chatBusy=true;chatError='';const version=chatVersion;chatController=new AbortController();if(location.hash==='#chat')route();const timeout=setTimeout(()=>chatController?.abort(),60000);try{if(!chatConfig){const config=await fetch('/api/config',{signal:chatController.signal});if(!config.ok)throw Error('The AI server is unavailable. Run Aura with python server.py.');chatConfig=await config.json();}if(!chatConfig.configured)throw Error('AI is not configured. Set GEMINI_API_KEY on the server and restart Aura.');const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','X-Aura-Token':chatConfig.token},signal:chatController.signal,body:JSON.stringify({messages:chatMessages.slice(-39),mode:chatMode,...(window.auraChatContext?window.auraChatContext(chatMessages.at(-1)?.text||''):{} )})});const data=await response.json();if(!response.ok){if(response.status===403)chatConfig=null;throw Error(data.error||'Aura could not respond. Please try again.');}if(version===chatVersion){chatMessages.push({role:'assistant',text:data.text});if(window.auraRememberUsed)window.auraRememberUsed(data.memoryIds||[]);}}catch(error){if(version===chatVersion)chatError=error.name==='AbortError'?'The response took too long. You can retry.':error.message;}finally{clearTimeout(timeout);if(version===chatVersion){chatBusy=false;chatController=null;if(location.hash==='#chat')route();}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mood||b.dataset.action==='mood')renderCats();if(b.dataset.cat){b.classList.remove('petted');void b.offsetWidth;b.classList.add('petted');}if(b.dataset.cats){if(b.dataset.cats==='hide')catsHidden=true;if(b.dataset.cats==='show')catsHidden=false;if(b.dataset.cats==='pause')document.body.classList.toggle('cats-paused');renderCats();}if(b.dataset.starter){chatDraft=b.dataset.starter;$('#chat-input').value=chatDraft;$('#chat-input').focus();}if(b.dataset.mode){chatMode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}if(b.dataset.chat==='retry')sendChat(true);if(b.dataset.chat==='new'&&(!chatMessages.length||confirm('Start a new conversation? This clears the chat from this tab. Save to your journal first if you want to keep it.'))){chatVersion++;chatController?.abort();chatMessages=[];chatDraft='';chatBusy=false;chatError='';route();}if(b.dataset.chat==='save'){if(!chatMessages.length){toast('Start a conversation first.');return;}state.entries.push({id:crypto.randomUUID(),date:stamp(),title:'Conversation with Aura',text:chatMessages.map(m=>(m.role==='user'?'You':'Aura (AI)')+':\n'+m.text).join('\n\n')});save();toast('Conversation copied to your journal.');}if(b.dataset.action==='clear'&&window.auraDataCleared){window.auraDataCleared=false;chatVersion++;chatController?.abort();chatMessages=[];chatDraft='';chatBusy=false;chatError='';renderCats();}});
route();

const brandLogo=$('.logo');if(brandLogo)brandLogo.innerHTML=catArt('#7a9382','#526d5b');
